<template><Layout><div class="breadcrumb"><Link :href="route('dashboard')">Overview</Link><span>›</span>Users</div><div class="page-header"><div><div class="eyebrow">COMMUNITY</div><h1>Users</h1><p>View and manage marketplace customer accounts.</p></div></div><section class="user-summary"><div><strong>{{ users.length }}</strong><span>Total users</span></div><div><strong>{{ approved }}</strong><span>Verified users</span></div><div><strong>{{ sellers }}</strong><span>Active sellers</span></div></section><section class="listing-panel"><div class="listing-toolbar user-toolbar"><div class="list-search"><svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></svg><input v-model="query" placeholder="Search name, phone or email…"/></div><select v-model="filter"><option value="all">All users</option><option value="approved">Verified</option><option value="pending">Unverified</option><option value="seller">Sellers</option></select><span>{{ filtered.length }} users</span></div><div v-if="filtered.length" class="users-list"><div class="user-row user-head"><span>User</span><span>Phone</span><span>Listings</span><span>Trust</span><span>Status</span><span></span></div><Link v-for="user in filtered" :key="user.id" :href="route('users.show',user.id)" class="user-row"><div class="user-cell"><span class="user-avatar"><img v-if="user.image" :src="user.image"/><b v-else>{{ initial(user.name) }}</b></span><div><strong>{{ user.name }}</strong><small>{{ user.email||`User #${user.id}` }}</small></div></div><span>{{ user.phone||'—' }}</span><span>{{ user.selling_products_count }}</span><span>{{ user.trust_level }}/5</span><span class="verification" :class="{pending:!user.is_approved}">{{ user.is_approved?'Verified':'Unverified' }}</span><b>›</b></Link></div><div v-else class="empty-state"><div>⌕</div><strong>No users found</strong><p>Try changing your search or filter.</p></div></section></Layout></template>
<script setup>import{ref,computed,onMounted}from'vue';import{usePage}from'@inertiajs/vue3';import{useToast}from'vue-toastification';import{route}from'ziggy-js';import Layout from'../Layouts/Layout.vue';const props=defineProps({users:{type:Array,default:()=>[]}}),query=ref(''),filter=ref('all');const approved=computed(()=>props.users.filter(u=>u.is_approved).length),sellers=computed(()=>props.users.filter(u=>u.selling_products_count>0).length);const filtered=computed(()=>{const q=query.value.toLowerCase();return props.users.filter(u=>[u.name,u.phone,u.email].some(x=>x?.toLowerCase().includes(q))&&(filter.value==='all'||filter.value==='approved'&&u.is_approved||filter.value==='pending'&&!u.is_approved||filter.value==='seller'&&u.selling_products_count>0))});const initial=n=>(n||'?').charAt(0).toUpperCase();const page=usePage(),toast=useToast();onMounted(()=>{if(page.props.flash?.success)toast.success(page.props.flash.success)});</script>
